  final Uint8List glyphPng;
  final int size;
  final Uint32List bbox;
  final int sourceWidth;
  final int sourceHeight;
  final double confidence;
  final bool ambiguous;
  final String method;
  final List<String> notes;

  const PreviewResult({
    required this.png,
    required this.glyphPng,
    required this.size,
    required this.bbox,
    required this.sourceWidth,
    required this.sourceHeight,
    required this.confidence,
    required this.ambiguous,
    required this.method,
    required this.notes,
  });

  @override
  int get hashCode =>
      png.hashCode ^
      glyphPng.hashCode ^
      size.hashCode ^
      bbox.hashCode ^
      sourceWidth.hashCode ^
      sourceHeight.hashCode ^
      confidence.hashCode ^
      ambiguous.hashCode ^
      method.hashCode ^
      notes.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is PreviewResult &&
          runtimeType == other.runtimeType &&
          png == other.png &&
          glyphPng == other.glyphPng &&
          size == other.size &&
          bbox == other.bbox &&
          sourceWidth == other.sourceWidth &&
          sourceHeight == other.sourceHeight &&
          confidence == other.confidence &&
          ambiguous == other.ambiguous &&
          method == other.method &&
          notes == other.notes;
}

class ProcessSettings {
  final int size;
  final BackgroundSettings background;
  final PlacementSettings placement;
  final SegmentSettings segment;

  /// When set, the glyph is isolated by the local AI model.
  final AiSettings? ai;

  const ProcessSettings({
    required this.size,
    required this.background,
    required this.placement,
    required this.segment,
    this.ai,
  });

  @override
  int get hashCode =>
      size.hashCode ^
      background.hashCode ^
      placement.hashCode ^
      segment.hashCode ^
      ai.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is ProcessSettings &&
          runtimeType == other.runtimeType &&
          size == other.size &&
          background == other.background &&
          placement == other.placement &&
          segment == other.segment &&
          ai == other.ai;
}

enum SegMode { auto, keepAlpha, removeBackground, none }

class SegmentSettings {
  final SegMode mode;
  final double tolerance;
  final bool removeHoles;
  final bool refineEdges;

  const SegmentSettings({
    required this.mode,
    required this.tolerance,
    required this.removeHoles,
    required this.refineEdges,
  });

  @override
  int get hashCode =>
      mode.hashCode ^
      tolerance.hashCode ^
      removeHoles.hashCode ^
      refineEdges.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is SegmentSettings &&
          runtimeType == other.runtimeType &&
          mode == other.mode &&
          tolerance == other.tolerance &&
          removeHoles == other.removeHoles &&
          refineEdges == other.refineEdges;
}

