      identical(this, other) ||
      other is TranslucentSettings &&
          runtimeType == other.runtimeType &&
          brightness == other.brightness &&
          frost == other.frost &&
          transparency == other.transparency &&
          tint == other.tint &&
          contrast == other.contrast &&
          border == other.border &&
          reflection == other.reflection &&
          depth == other.depth &&
